"""Seating charts, sorted by last name."""

from typing import List

from rosterkit.models import Student
from rosterkit.errors import ProjectError


def _sort_key(student: Student) -> tuple:
    last = student.last_name.casefold()
    return (last, student.first_name.casefold())


def _check_input(students: List[Student], seats: int):
    if seats <= 0:
        raise ProjectError("seats per row must be positive")
    if not students:
        raise ProjectError("no students to seat")


def _split_rows(items: List[Student], seats: int) -> list:
    size = len(items)
    return [
        items[start:start + seats]
        for start in range(0, size, seats)
    ]


def _format_row(number: int, group: List[Student]) -> str:
    names = " | ".join(item.display_name for item in group)
    return f"Row {number}: {names}"


def _build_lines(ordered: list, seats: int) -> List[str]:
    groups = _split_rows(ordered, seats)
    return [
        _format_row(number, group)
        for number, group in enumerate(groups, 1)
    ]


# ---
def seating_rows(students: list, seats: int) -> List[str]:
    """One line per row, sorted by last name."""
    _check_input(students, seats)
    ordered = sorted(students, key=_sort_key)
    return _build_lines(ordered, seats)

